const dispatchThreadMutation = (
  ...args: Parameters<typeof dispatchSingleThreadMutation>
) => Effect.gen(function* () {
  const [command, events, effects] = args;
  if (command.type !== "thread.settle") {
    return yield* dispatchSingleThreadMutation(command, events, effects);
  }
  const ids = yield* projectionStore.getSettlementThreadIds(command.threadId)
    .pipe(mapDispatchError(command));
  for (const threadId of ids) {
    yield* dispatchSingleThreadMutation({ ...command, threadId }, events, effects);
  }
});

